<?= App\Core\View::partial('reports/_filters', get_defined_vars()) ?>
<div class="card"><div class="table-responsive"><table class="table table-sm table-hover mb-0"><thead><tr><th>#</th><th>Référence</th><th>Article</th><th>Catégorie</th><th class="num">Quantité</th><th class="num">CA net</th><?php if ($fin): ?><th class="num">Marge</th><th class="num">Taux</th><?php endif; ?></tr></thead><tbody>
<?php foreach ($rows as $i => $r): ?><tr><td><?= $i + 1 ?></td><td class="small"><?= e($r['reference']) ?></td><td><a href="<?= e(url('/products/' . $r['id'])) ?>"><?= e($r['name']) ?></a></td><td><?= e($r['category'] ?? '') ?></td><td class="num"><?= qty($r['qty']) ?></td><td class="num"><?= money($r['revenue']) ?></td><?php if ($fin): ?><td class="num"><?= money($r['margin']) ?></td><td class="num <?= (float) $r['margin'] < 0 ? 'text-danger' : '' ?>"><?= (float) $r['revenue'] > 0 ? number_format((float) $r['margin'] / (float) $r['revenue'] * 100, 1, ',', ' ') : 0 ?> %</td><?php endif; ?></tr><?php endforeach; ?>
